export function isImageReviewedCatalogTaxonomyOverride(override) {
  return Boolean(
    override?.approved &&
    override?.imageReviewed === true &&
    String(override?.imageUrl || "").trim() &&
    String(override?.reviewedAt || "").trim() &&
    String(override?.reason || "").trim(),
  );
}
